import java.io.*;import java.math.*;import java.security.*;import java.text.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;import java.util.regex.*;import java.util.stream.*;import static java.util.stream.Collectors.joining;import static java.util.stream.Collectors.toList;class Result {public static long getWays(int n, List<Long> c) {long[] dp = new long[n + 1];dp[0] = 1;for (Long coin : c) {int coinVal = coin.intValue();for (int j = coinVal; j <= n; j++) {dp[j] += dp[j - coinVal];}}return dp[n];}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int n = Integer.parseInt(firstMultipleInput[0]);int m = Integer.parseInt(firstMultipleInput[1]);List<Long> c = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Long::parseLong).collect(toList());long ways = Result.getWays(n, c);bufferedWriter.write(String.valueOf(ways));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}